-- Standard variants of the Report Centre: one to three shared parameter sets per report that a
-- broker uses most (this month, last month, year to date, expiring next, my branch, open only),
-- configuration of every environment. Users cannot delete them; their own variants are listed
-- apart ("My Variants"), and each user may mark one of his variants as the default of a report.
-- Date values are keywords resolved when the variant is applied (TODAY, MONTH_START, MONTH_END,
-- YEAR_START, YEAR_END, PREV_MONTH_START, PREV_MONTH_END, NEXT_MONTH_START, NEXT_MONTH_END,
-- IN_THREE_MONTHS, IN_TWELVE_MONTHS, TWELVE_MONTHS_AGO, PREV_YEAR_START, PREV_YEAR_END,
-- CURRENT_YEAR, PREV_YEAR) and MY_BRANCH is the branch of the user's workspace.

alter table nbr_report_variant
    add column standard        boolean not null default false,
    add column default_variant boolean not null default false;

on conflict (lower(owner), report_code, lower(name)) do nothing;
